<style>
.fd{--fd-gold:#e3c48b;--fd-muted:#aab7c8;color:#eef3fa;font-family:inherit;min-width:0}.fd-hero{padding:30px;border:1px solid #d8bc8055;border-radius:24px;background:radial-gradient(ellipse at 90% 0,#c69a4e25,transparent 60%),linear-gradient(125deg,#172333,#0e1620)}.fd-kicker{font-size:11px;text-transform:uppercase;letter-spacing:.25em;color:var(--fd-gold);font-weight:700}.fd h3{font-size:clamp(28px,3vw,42px);font-weight:650;letter-spacing:-.035em}.fd-muted{color:var(--fd-muted);font-size:13px;line-height:1.7}.fd-nav{display:flex;gap:8px;overflow:auto;padding:8px 0}.fd-nav a,.fd-link{display:inline-flex;align-items:center;justify-content:center;padding:11px 16px;border:1px solid #ffffff22;border-radius:12px;font-size:13px;white-space:nowrap;text-decoration:none}.fd-nav a[aria-current=page]{color:#171a21;background:linear-gradient(135deg,#f0dcb3,#bb9659);border-color:#e9d2a7;font-weight:700;box-shadow:0 4px 20px #d9b36a20}.fd-panel{background:linear-gradient(140deg,#172331,#101923);border:1px solid #b5c8e025;border-radius:20px;padding:24px;min-width:0}.fd-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px}.fd-card{border:1px solid #ffffff15;border-top:2px solid #d9b77a88;background:linear-gradient(140deg,#1a293a,#121d29);border-radius:16px;padding:20px}.fd-card strong{display:block;font-size:26px;letter-spacing:-.03em;margin:10px 0}.fd-form{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:14px;align-items:end}.fd label{display:block;font-size:12px;color:#bdc9d8}.fd input,.fd select,.fd textarea{display:block;width:100%;margin-top:7px;padding:10px 12px;border:1px solid #ffffff25;border-radius:10px;background:#0e1722;color:#edf2f8;font:inherit;color-scheme:dark}.fd button{padding:11px 18px;background:linear-gradient(135deg,#ebd2a5,#bd985c);color:#171c24;border-radius:10px;font-size:13px;font-weight:700}.fd button:disabled{opacity:.4}.fd-table-wrap{overflow:auto}.fd table{width:100%;border-collapse:collapse;font-size:13px}.fd th{text-align:left;font-size:10px;letter-spacing:.1em;text-transform:uppercase;color:#9aaec5;border-bottom:1px solid #ffffff25;padding:14px 10px}.fd td{padding:16px 10px;border-bottom:1px solid #ffffff12;vertical-align:top;min-width:110px}.fd-badge{display:inline-flex;padding:4px 9px;background:#e2bf7620;border:1px solid #e2bf7644;color:#eacf9e;border-radius:7px;font-size:11px}.fd-good{background:#65d6b320;border-color:#65d6b355;color:#9de4cc}.fd details>summary{cursor:pointer;font-weight:600;font-size:13px}.fd-person{border-radius:30px}.fd-notice{padding:12px 16px;border-left:2px solid var(--fd-gold);background:#e4c18109;font-size:12px;color:#bac7d8;line-height:1.7}.fd svg{display:block;width:100%;height:360px}.fd a:focus-visible,.fd button:focus-visible,.fd summary:focus-visible{outline:2px solid #e8ce9f;outline-offset:3px}@media(max-width:1100px){.fd-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:640px){.fd-panel,.fd-hero{padding:17px}.fd-grid{grid-template-columns:1fr}.fd svg{height:290px}.fd-card strong{font-size:23px}}
</style>
